/* @lc app=leetcode id=3165 lang=kotlin */ class Solution { fun mg(l: LongArray, r: LongArray): LongArray = LongArray(4) { i -> listOf(0 to 0, 0 to 1, 1 to 0).maxOf { (x, y) -> l[i / 2 * 2 + x] + r[y * 2 + i % 2] }.coerceAtLeast(-1_000_000_000_000_000L) } fun lf(v: Long) = longArrayOf(0L, -1_000_000_000_000_000L, -1_000_000_000_000_000L, v) fun maximumSumSubsequence(nums: IntArray, queries: Array<IntArray>): Int = generateSequence(1) { it * 2 }.first { it >= nums.size }.let { sz -> Array(2 * sz) { longArrayOf(0L, -1_000_000_000_000_000L, -1_000_000_000_000_000L, -1_000_000_000_000_000L) }.also { t -> nums.indices.forEach { t[sz + it] = lf(nums[it].toLong()) } }.also { t -> (sz - 1 downTo 1).forEach { t[it] = mg(t[2 * it], t[2 * it + 1]) } }.let { t -> queries.fold(0L) { acc, (p, x) -> t.set(sz + p, lf(x.toLong())).let { generateSequence((sz + p) / 2) { it / 2 }.takeWhile { it >= 1 }.forEach { i -> t[i] = mg(t[2 * i], t[2 * i + 1]) } }.let { (acc + t[1].max()) % 1_000_000_007 } }.toInt() } } }